<?php
declare(strict_types=1); namespace App\Controllers;
use App\Core\Auth;use App\Core\Controller;use App\Core\Flash;use App\Models\Notification;use App\Models\User;use App\Services\RememberMeService;
final class AuthController extends Controller { public function __construct(private readonly User $users,private readonly Auth $auth,private readonly RememberMeService $rememberMe,private readonly Notification $notifications){} public function home():void{$this->auth->check()?$this->redirect('dashboard'):$this->view('auth/home',['pageTitle'=>'Welcome']);} public function loginForm():void{if($this->auth->check())$this->redirect('dashboard');$this->view('auth/login',['pageTitle'=>'Sign in']);} public function login():void{$this->requirePost();$this->requireCsrf();$username=trim((string)($_POST['username']??''));$password=(string)($_POST['password']??'');$user=$this->users->findByUsername($username);if($user===null||!password_verify($password,(string)$user['password'])){Flash::add('error','Invalid username or password.');$this->redirect('login');}$this->auth->login($user);isset($_POST['remember'])?$this->rememberMe->issue((int)$user['user_id']):$this->rememberMe->clear();$this->redirect('dashboard');} public function registerForm():void{if($this->auth->check())$this->redirect('dashboard');$this->view('auth/register',['pageTitle'=>'Create account']);} public function register():void{$this->requirePost();$this->requireCsrf();$name=trim((string)($_POST['full_name']??''));$username=trim((string)($_POST['username']??''));$email=trim((string)($_POST['email']??''));$password=(string)($_POST['password']??'');$confirm=(string)($_POST['confirm_password']??'');$role=(string)($_POST['role']??'Student');if($name===''||mb_strlen($name)>100)Flash::add('error','Full name is required and must be 100 characters or fewer.');elseif(!preg_match('/^[A-Za-z0-9_]{4,30}$/',$username))Flash::add('error','Username must be 4-30 letters, numbers, or underscores.');elseif(!filter_var($email,FILTER_VALIDATE_EMAIL))Flash::add('error','Enter a valid email address.');elseif(strlen($password)<6)Flash::add('error','Password must be at least 6 characters.');elseif($password!==$confirm)Flash::add('error','Password confirmation does not match.');elseif(!in_array($role,['Student','Admin'],true))Flash::add('error','Choose a valid account role.');elseif(!isset($_POST['accept_terms']))Flash::add('error','You must accept the Terms & Conditions.');elseif($this->users->usernameOrEmailExists($username,$email))Flash::add('error','That username or email is already registered.');else{$id=$this->users->create($username,$email,$password,$name,$role);$this->notifications->create($id,'success','Welcome to SRO','Your account is ready. Start by setting up your routine.','dashboard');Flash::add('success','Account created. You can now sign in.');$this->redirect('login');}$this->redirect('register');} public function logout():void{$this->requirePost();$this->requireCsrf();$this->rememberMe->clear();$this->auth->logout();\App\Core\Session::start();Flash::add('success','You have been logged out.');$this->redirect('');} }
